properties.query:
let alertWindow = 20m;
let cpuGate = 90.0;
let memRatioGate = 0.9;
let rxPacketGate = 50000;
let ResourceSpike =
    UAVResourceMetrics_CL
    | where TimeGenerated > ago(alertWindow)
    | extend MemRatio = todouble(MemoryUsageBytes) / MemoryLimitBytes
    | summarize MaxCpu = max(CpuUsagePct), MaxMemRatio = max(MemRatio) by ContainerName, TimeBin = bin(TimeGenerated, 5m)
    | where MaxCpu > cpuGate and MaxMemRatio > memRatioGate;
let NetBurst =
    UAVDatalink_CL
    | where TimeGenerated > ago(alertWindow)
    | summarize MaxRxPackets = max(RxPackets) by ContainerName, TimeBin = bin(TimeGenerated, 5m)
    | where MaxRxPackets > rxPacketGate;
ResourceSpike
| join kind=inner (NetBurst) on ContainerName, TimeBin
| summarize SustainedBins = count(), FirstBin = min(TimeBin), LastBin = max(TimeBin), PeakCpu = max(MaxCpu), PeakMemRatio = max(MaxMemRatio), PeakRxPackets = max(MaxRxPackets) by ContainerName
| extend DurationMin = datetime_diff("minute", LastBin, FirstBin)
| where SustainedBins >= 2 and DurationMin >= 5
| extend TriggerReason = strcat(ContainerName, "_리소스고갈DoS_CPU", tostring(toint(PeakCpu)), "%_RxPkt", tostring(PeakRxPackets))
| extend Severity = "High"
| project TimeGenerated = LastBin, FirstBin, ContainerName, PeakCpu, PeakMemRatio, PeakRxPackets, SustainedBins, DurationMin, TriggerReason, Severity
| order by TimeGenerated desc
